// ⚠️ 自动生成，勿手改。源文件：src/page.html
export const PAGE_HTML = "<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>PERSONA-OS // 鲸鱼指挥舱</title>\n<style>\n  :root{\n    --deep:#0A1128;      /* 深空蓝底 */\n    --panel:#1B263B;     /* 面板 */\n    --cyan:#00F0FF;      /* 赛博青（发光边框） */\n    --white:#FFFFFF;     /* 女仆白 */\n    --sea:#5BC0BE;       /* 浅海蓝强调 */\n    --ok:#3ef0a0; --bad:#ff4d6d; --dim:#6b7f99;\n  }\n  *{box-sizing:border-box;image-rendering:pixelated}\n  html,body{height:100%}\n  body{\n    margin:0;background:var(--deep);color:var(--white);\n    font-family:\"VT323\",\"Zpix\",\"Cascadia Mono\",Consolas,\"Microsoft YaHei\",monospace;\n    font-size:16px;letter-spacing:.02em;overflow-x:hidden;\n    background-image:\n      repeating-linear-gradient(0deg,rgba(0,240,255,.035) 0 1px,transparent 1px 3px),\n      radial-gradient(900px 500px at 15% -10%,#122a52 0%,transparent 60%),\n      radial-gradient(700px 400px at 100% 0%,#1a1a4a 0%,transparent 55%);\n  }\n  /* 像素噪点 */\n  body::after{\n    content:\"\";position:fixed;inset:0;pointer-events:none;opacity:.05;z-index:9999;\n    background-image:url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='4' height='4'><rect width='1' height='1' fill='white'/><rect x='2' y='2' width='1' height='1' fill='white'/></svg>\");\n  }\n\n  /* ---------- 顶栏 ---------- */\n  header{\n    display:flex;align-items:center;gap:12px;padding:10px 16px;\n    border-bottom:4px solid var(--cyan);background:rgba(27,38,59,.85);\n    box-shadow:0 0 18px rgba(0,240,255,.35);\n  }\n  .burger{\n    width:38px;height:34px;display:flex;flex-direction:column;justify-content:center;gap:5px;\n    padding:0 8px;border:2px solid var(--cyan);background:transparent;cursor:pointer;\n  }\n  .burger span{display:block;height:3px;background:var(--cyan)}\n  .burger:active{transform:translate(2px,2px)}\n  h1{margin:0;font-size:20px;letter-spacing:.22em;color:var(--cyan);text-shadow:0 0 10px rgba(0,240,255,.6)}\n  header .spacer{flex:1}\n  header .clock{color:var(--sea);font-size:15px}\n\n  /* ---------- 菜单抽屉（☰ 里的两个按钮） ---------- */\n  #drawer{\n    position:fixed;left:0;top:54px;width:280px;z-index:1000;display:none;\n    border:4px solid var(--cyan);border-left:none;background:rgba(10,17,40,.97);\n    box-shadow:6px 6px 0 rgba(0,240,255,.25);padding:12px;\n  }\n  #drawer.open{display:block}\n  #drawer h3{margin:0 0 10px;font-size:14px;letter-spacing:.18em;color:var(--sea)}\n  .dbtn{\n    display:block;width:100%;text-align:left;margin-bottom:8px;padding:9px 10px;cursor:pointer;\n    border:2px solid var(--cyan);background:rgba(0,240,255,.08);color:var(--white);font:inherit;font-size:15px;\n  }\n  .dbtn:hover{background:rgba(0,240,255,.2)}\n  .dbtn:active{transform:translate(2px,2px)}\n  .dbtn small{display:block;color:var(--dim);font-size:12px;margin-top:2px}\n  .dbtn.danger{border-color:var(--bad);background:rgba(255,77,109,.1)}\n  .dbtn.danger:hover{background:rgba(255,77,109,.25)}\n  #drawer .note{font-size:12px;color:var(--dim);line-height:1.5;margin-top:8px}\n\n  /* ---------- 主布局 ---------- */\n  main{\n    display:grid;grid-template-columns:minmax(320px,42%) 1fr;\n    grid-template-rows:auto 1fr;gap:14px;padding:14px;\n  }\n  .box{border:4px solid var(--cyan);background:var(--panel);box-shadow:0 0 14px rgba(0,240,255,.18);position:relative}\n  .box .cap{\n    position:absolute;top:-2px;left:10px;transform:translateY(-50%);\n    background:var(--deep);padding:0 8px;font-size:13px;color:var(--sea);letter-spacing:.16em;\n  }\n\n  /* 左上：立绘舱 */\n  #avatarBox{grid-column:1;grid-row:1;min-height:300px;display:flex;align-items:center;justify-content:center;overflow:hidden}\n  #avatarBox img{width:100%;height:100%;object-fit:contain}\n  #avatarBox.speaking{border-color:var(--white);animation:speakPulse .55s steps(2,end) infinite}\n  @keyframes speakPulse{\n    0%,100%{box-shadow:0 0 10px rgba(0,240,255,.35)}\n    50%{box-shadow:0 0 26px 6px rgba(255,255,255,.75)}\n  }\n  #avatarBox .fallback{color:var(--dim);font-size:14px;text-align:center;padding:20px}\n\n  /* 左下：状态与操作 */\n  #statusBox{grid-column:1;grid-row:2;padding:22px 14px 14px}\n  .leds{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n  .led{display:flex;align-items:center;gap:8px;padding:6px 8px;border:2px solid rgba(0,240,255,.25);background:rgba(0,0,0,.25)}\n  .led i{width:10px;height:10px;background:var(--bad);flex:none}\n  .led i.up{background:var(--ok);animation:ledBreath 1.8s steps(2,end) infinite}\n  .led i.down{animation:ledBlink 1.2s steps(2,end) infinite}\n  @keyframes ledBreath{0%,100%{box-shadow:0 0 0 rgba(62,240,160,.8)}50%{box-shadow:0 0 10px 2px rgba(62,240,160,.8)}}\n  @keyframes ledBlink{50%{opacity:.2}}\n  .led b{font-weight:400;font-size:14px}\n  .led em{font-style:normal;color:var(--dim);font-size:12px;margin-left:auto}\n  .meters{margin-top:12px}\n  .meter{margin-top:8px}\n  .meter .lbl{display:flex;justify-content:space-between;font-size:13px;color:var(--dim);margin-bottom:3px}\n  .meter .bar{height:10px;border:2px solid rgba(0,240,255,.4);background:#08101f}\n  .meter .bar>i{display:block;height:100%;background:linear-gradient(90deg,var(--sea),var(--cyan));width:0%}\n\n  /* 右侧：弹幕互动区 */\n  #chatBox{grid-column:2;grid-row:1;display:flex;flex-direction:column;min-height:300px;padding:18px 10px 10px}\n  #feed{flex:1;overflow:auto;background:#04070f;border:2px solid rgba(0,240,255,.22);padding:10px;font-size:14px;line-height:1.55}\n  #feed .row{margin-bottom:6px;word-break:break-all;white-space:pre-wrap}\n  #feed .me{color:var(--cyan)}\n  #feed .bot{color:var(--ok)}\n  #feed .err{color:var(--bad)}\n  #feed .sys{color:var(--dim)}\n  .cmd{display:flex;gap:8px;margin-top:8px}\n  .cmd input{\n    flex:1;font:inherit;font-size:16px;padding:9px 10px;color:var(--white);\n    background:#04070f;border:2px solid var(--cyan);outline:none;\n  }\n  .cmd input:focus{box-shadow:0 0 12px rgba(0,240,255,.45)}\n  .cmd button{\n    font:inherit;font-size:16px;padding:9px 18px;cursor:pointer;color:var(--deep);\n    background:var(--cyan);border:2px solid var(--cyan);\n  }\n  .cmd button:hover{background:var(--white)}\n  .cmd button:active{transform:translate(2px,2px)}\n  .cmd button:disabled{opacity:.45;cursor:default;transform:none}\n\n  /* 右下：CRT 画板 */\n  #crtBox{grid-column:2;grid-row:2;padding:18px 10px 10px;min-height:240px}\n  .crt{position:relative;width:100%;height:100%;min-height:200px;background:#03060c;overflow:hidden}\n  .crt img{width:100%;height:100%;object-fit:contain;display:block;filter:contrast(1.06) saturate(1.08)}\n  .crt::before{ /* 扫描线 */\n    content:\"\";position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.28;\n    background:repeating-linear-gradient(0deg,rgba(0,0,0,.55) 0 2px,transparent 2px 4px);\n  }\n  .crt::after{ /* 暗角 */\n    content:\"\";position:absolute;inset:0;pointer-events:none;z-index:3;\n    box-shadow:inset 0 0 60px rgba(0,0,0,.85);\n  }\n  .crt .hint{\n    position:absolute;inset:0;display:flex;align-items:center;justify-content:center;\n    color:var(--dim);font-size:14px;letter-spacing:.14em;z-index:1;\n  }\n\n  @media (max-width:900px){\n    main{grid-template-columns:1fr;grid-template-rows:auto}\n    #chatBox,#crtBox{grid-column:1}\n  }\n</style>\n</head>\n<body>\n<header>\n  <button class=\"burger\" id=\"burger\" title=\"菜单\"><span></span><span></span><span></span></button>\n  <h1>PERSONA-OS // 鲸鱼指挥舱</h1>\n  <span class=\"spacer\"></span>\n  <span class=\"clock\" id=\"clock\">--:--:--</span>\n</header>\n\n<!-- ☰ 菜单：只放真能做的事 -->\n<div id=\"drawer\">\n  <h3>// 舰桥控制</h3>\n  <button class=\"dbtn danger\" id=\"btnRestart\" data-name=\"IndexTTS2\">\n    重启 TTS\n    <small>POST :8010/restart?name=IndexTTS2</small>\n  </button>\n  <button class=\"dbtn danger\" id=\"btnRestartPainter\" data-name=\"Painter\">\n    重启 Painter\n    <small>POST :8010/restart?name=Painter</small>\n  </button>\n  <button class=\"dbtn\" id=\"btnStartAll\">\n    拉起全部微服务\n    <small>POST :8010/start-all（不会动被手动停掉的）</small>\n  </button>\n  <button class=\"dbtn\" id=\"btnClearFeed\">\n    清空弹幕流\n    <small>纯前端</small>\n  </button>\n  <button class=\"dbtn\" id=\"btnRawStatus\">\n    查看 /api/status 原始 JSON\n    <small>排查用</small>\n  </button>\n  <div class=\"note\" id=\"ctlNote\">控制接口未探测</div>\n</div>\n\n<main>\n  <div class=\"box\" id=\"avatarBox\">\n    <span class=\"cap\">LIVE FEED</span>\n    <img id=\"avatar\" src=\"/assets/avatar.png\" alt=\"\" onerror=\"this.style.display='none';document.getElementById('avatarFallback').style.display='block'\">\n    <div class=\"fallback\" id=\"avatarFallback\" style=\"display:none\">立绘未就位<br><small>把图放到 web/assets/avatar.png</small></div>\n  </div>\n\n  <div class=\"box\" id=\"statusBox\">\n    <span class=\"cap\">SYSTEMS</span>\n    <div class=\"leds\" id=\"leds\"></div>\n    <div class=\"meters\">\n      <div class=\"meter\">\n        <div class=\"lbl\"><span>MEMORY</span><span id=\"memTxt\">-</span></div>\n        <div class=\"bar\"><i id=\"memBar\"></i></div>\n      </div>\n      <div id=\"gpuMeters\"></div>\n    </div>\n  </div>\n\n  <div class=\"box\" id=\"chatBox\">\n    <span class=\"cap\">DANMAKU // 指挥官测试台</span>\n    <div id=\"feed\"></div>\n    <div class=\"cmd\">\n      <input id=\"cmdInput\" placeholder=\"!画 像素风的猫\" autocomplete=\"off\">\n      <button id=\"sendBtn\">发送指令</button>\n    </div>\n  </div>\n\n  <div class=\"box\" id=\"crtBox\">\n    <span class=\"cap\">PIXEL ART // 画板</span>\n    <div class=\"crt\">\n      <div class=\"hint\" id=\"crtHint\">等待作画…</div>\n      <img id=\"paintBoard\" alt=\"\" style=\"display:none\">\n    </div>\n  </div>\n</main>\n\n<script>\nconst $ = (id) => document.getElementById(id)\nconst feed = $('feed')\nlet ctlOk = false\n\nfunction nowStr(){ return new Date().toLocaleTimeString('zh-CN',{hour12:false}) }\nsetInterval(()=>{ $('clock').textContent = nowStr() }, 1000)\n\nfunction pushLine(kind, text){\n  const d = document.createElement('div')\n  d.className = 'row ' + kind\n  d.textContent = text\n  feed.appendChild(d)\n  feed.scrollTop = feed.scrollHeight\n  while (feed.children.length > 400) feed.removeChild(feed.firstChild)\n}\n\n// ---------- 状态 ----------\nconst LED_MAP = [\n  ['memory','Memory :8001'],['painter','Painter :8002'],\n  ['audiocover','Audio :8005'],['indextts','TTS :9881'],\n  ['live','Director :9001'],['gamebot','GameBot :8003'],\n]\nfunction renderLeds(services){\n  const box = $('leds')\n  if (!box.children.length) {\n    box.innerHTML = LED_MAP.map(([k,label]) => `<div class=\"led\" data-k=\"${k}\"><i></i><b>${label}</b><em></em></div>`).join('')\n  }\n  for (const [k] of LED_MAP){\n    const s = services.find(x => x.key === k)\n    const el = box.querySelector(`[data-k=\"${k}\"]`)\n    if (!el || !s) continue\n    el.querySelector('i').className = s.up ? 'up' : 'down'\n    el.querySelector('em').textContent = s.up ? s.ms + 'ms' : 'off'\n  }\n}\nfunction renderHost(host){\n  $('memBar').style.width = host.memPct + '%'\n  $('memTxt').textContent = host.memPct + '%'\n  const g = $('gpuMeters')\n  if (!host.gpus || !host.gpus.length){\n    g.innerHTML = `<div class=\"meter\"><div class=\"lbl\"><span>GPU</span><span>${host.gpuError ? 'n/a' : '无'}</span></div></div>`\n    return\n  }\n  g.innerHTML = host.gpus.map(x => {\n    const pct = x.memTotalMb ? Math.round(x.memUsedMb / x.memTotalMb * 100) : 0\n    return `<div class=\"meter\"><div class=\"lbl\"><span>GPU ${x.name.slice(0,18)}</span><span>${x.memUsedMb}/${x.memTotalMb} MB</span></div>\n      <div class=\"bar\"><i style=\"width:${pct}%\"></i></div></div>`\n  }).join('')\n}\nasync function pollStatus(){\n  try{\n    const r = await fetch('/api/status',{cache:'no-store'})\n    if(!r.ok) return\n    const j = await r.json()\n    renderLeds(j.services)\n    renderHost(j.host)\n  }catch(_){}\n}\n\n// ---------- 画板 ----------\nlet lastPaintTag = ''\nasync function pollPaint(){\n  try{\n    const r = await fetch('/api/latest-paint?tag=' + Date.now(), {cache:'no-store'})\n    if (r.status === 404){ return }\n    if(!r.ok) return\n    const tag = r.headers.get('x-paint-mtime') || ''\n    if (tag && tag === lastPaintTag) return\n    lastPaintTag = tag\n    const blob = await r.blob()\n    const url = URL.createObjectURL(blob)\n    const img = $('paintBoard')\n    const old = img.dataset.url\n    img.onload = () => { if (old) URL.revokeObjectURL(old) }\n    img.dataset.url = url\n    img.src = url\n    img.style.display = 'block'\n    $('crtHint').style.display = 'none'\n  }catch(_){}\n}\n\n// ---------- 发指令 ----------\nlet sending = false\nasync function sendCmd(){\n  const text = $('cmdInput').value.trim()\n  if (!text || sending) return\n  sending = true; $('sendBtn').disabled = true\n  pushLine('me', '『面板指挥官』 ' + text)\n  try{\n    const r = await fetch('/api/danmaku', {\n      method:'POST', headers:{'content-type':'application/json'},\n      body: JSON.stringify({ text })\n    })\n    const j = await r.json()\n    if (j.ok) pushLine('bot', '← ' + JSON.stringify(j.reply))\n    else pushLine('err', '✗ ' + (j.error || '发送失败'))\n  }catch(e){\n    pushLine('err', '✗ 请求失败：' + e.message)\n  }finally{\n    sending = false; $('sendBtn').disabled = false; $('cmdInput').value = ''\n  }\n}\n$('sendBtn').onclick = sendCmd\n$('cmdInput').addEventListener('keydown', e => { if (e.key === 'Enter') sendCmd() })\n\n// ---------- ☰ 菜单 ----------\nconst drawer = $('drawer')\n$('burger').onclick = (e) => { e.stopPropagation(); drawer.classList.toggle('open') }\ndocument.addEventListener('click', (e) => { if (!drawer.contains(e.target) && e.target !== $('burger')) drawer.classList.remove('open') })\n\nasync function ctl(path, label){\n  pushLine('sys', '› ' + label)\n  try{\n    const r = await fetch('/api/control' + path, { method:'POST' })\n    const j = await r.json()\n    pushLine(j.ok ? 'bot' : 'err', '← ' + JSON.stringify(j))\n  }catch(e){\n    pushLine('err', '✗ 控制接口不可用：' + e.message)\n  }\n}\ndocument.querySelectorAll('[data-name]').forEach(b => {\n  b.onclick = () => ctl('/restart?name=' + encodeURIComponent(b.dataset.name), '重启 ' + b.dataset.name)\n})\n$('btnStartAll').onclick = () => ctl('/start-all', '拉起全部微服务')\n$('btnClearFeed').onclick = () => { feed.innerHTML = ''; pushLine('sys','// 已清空') }\n$('btnRawStatus').onclick = async () => {\n  const j = await fetch('/api/status').then(r=>r.json())\n  pushLine('sys', JSON.stringify(j, null, 1))\n}\n\nasync function probeCtl(){\n  try{\n    const r = await fetch('/api/control/health')\n    const j = await r.json()\n    ctlOk = !!j.ok\n    $('ctlNote').textContent = ctlOk ? '✅ 控制接口在线（' + (j.services||[]).join(' / ') + '）' : '⚠️ 控制接口返回异常'\n  }catch(_){\n    $('ctlNote').textContent = '⚠️ 控制接口 :8010 未启动（重启/拉起按钮会失败）'\n  }\n}\n\n// TTS 播放时立绘框闪：目前 TTS 在别的进程，这里只能由弹幕回包临时触发\nfunction flashAvatar(ms){\n  const b = $('avatarBox')\n  b.classList.add('speaking')\n  setTimeout(()=>b.classList.remove('speaking'), ms || 1600)\n}\n\npushLine('sys','// 鲸鱼指挥舱已就绪')\nprobeCtl()\npollStatus()\npollPaint()\nsetInterval(pollStatus, 2000)\nsetInterval(pollPaint, 100)\nsetInterval(probeCtl, 15000)\n</script>\n</body>\n</html>\n"
